window.__finlexDocLoaded(4,{"id":4,"articles":[{"id":93,"no":"第一条","heading":"","text":"为了规范投资性房地产的确认、计量和相关信息的披露，根据《企业会计准则——基本准则》，制定本准则。","seq":0,"links":[{"doc_id":5,"tier":"L3","score":64,"rel_kind":"cites","target_seq":1,"target_art_no":"第二条","dir":"in","note":"正文显式引用《企业会计准则第03号——投资性房地产》"},{"doc_id":7,"tier":"L3","score":64,"rel_kind":"cites","target_seq":1,"target_art_no":"第二条","dir":"in","note":"正文显式引用《企业会计准则第03号——投资性房地产》"},{"doc_id":9,"tier":"L3","score":64,"rel_kind":"cites","target_seq":2,"target_art_no":"第三条","dir":"in","note":"正文显式引用《企业会计准则第03号——投资性房地产》"},{"doc_id":42,"tier":"L3","score":64,"rel_kind":"cites","target_seq":2,"target_art_no":"第三条","dir":"in","note":"正文显式引用《企业会计准则第03号——投资性房地产》"}]},{"id":94,"no":"第二条","heading":"","text":"投资性房地产，是指为赚取租金或资本增值，或两者兼有而持有的房地产。 投资性房地产应当能够单独计量和出售。","seq":1},{"id":95,"no":"第三条","heading":"","text":"本准则规范下列投资性房地产： （一）已出租的土地使用权。 （二）持有并准备增值后转让的土地使用权。 （三）已出租的建筑物。","seq":2,"links":[{"doc_id":93,"tier":"L1","score":96,"rel_kind":"companion","target_seq":1,"target_art_no":"第2节","dir":"in","note":"指南详解（第2节）：锚定第三条（条文主题匹配）"}]},{"id":96,"no":"第四条","heading":"","text":"下列各项不属于投资性房地产： （一）自用房地产，即为生产商品、提供劳务或者经营管理而持有的房地产。 （二）作为存货的房地产。","seq":3,"links":[{"doc_id":93,"tier":"L1","score":96,"rel_kind":"companion","target_seq":1,"target_art_no":"第2节","dir":"in","note":"指南详解（第2节）：锚定第四条（条文主题匹配）"}]},{"id":97,"no":"第五条","heading":"","text":"下列各项适用其他相关会计准则： （一）企业代建的房地产，适用《企业会计准则第15号——建造合同》。 （二）投资性房地产的租金收入和售后租回，适用《企业会计准则第21号——租赁》。","seq":4,"links":[{"doc_id":21,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第21号——租赁》"}]},{"id":98,"no":"第六条","heading":"","text":"投资性房地产同时满足下列条件的，才能予以确认： （一）与该投资性房地产有关的经济利益很可能流入企业； （二）该投资性房地产的成本能够可靠地计量。","seq":5},{"id":99,"no":"第七条","heading":"","text":"投资性房地产应当按照成本进行初始计量。 （一）外购投资性房地产的成本，包括购买价款、相关税费和可直接归属于该资产的其他支出。 （二）自行建造投资性房地产的成本，由建造该项资产达到预定可使用状态前所发生的必要支出构成。 （三）以其他方式取得的投资性房地产的成本，按照相关会计准则的规定确定。","seq":6,"links":[{"doc_id":93,"tier":"L1","score":96,"rel_kind":"companion","target_seq":3,"target_art_no":"第4节","dir":"in","note":"指南详解（第4节）：锚定第七条（预定可使用状态）"}]},{"id":100,"no":"第八条","heading":"","text":"与投资性房地产有关的后续支出，满足本准则第六条规定的确认条件的，应当计入投资性房地产成本；不满足本准则第六条规定的确认条件的，应当在发生时计入当期损益。","seq":7},{"id":101,"no":"第九条","heading":"","text":"企业应当在资产负债表日采用成本模式对投资性房地产进行后续计量，但本准则第十条规定的除外。 采用成本模式计量的建筑物的后续计量，适用《企业会计准则第04号——固定资产》。 采用成本模式计量的土地使用权的后续计量，适用《企业会计准则第06号——无形资产》。","seq":8,"links":[{"doc_id":5,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第04号——固定资产》"},{"doc_id":7,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第06号——无形资产》"}]},{"id":102,"no":"第十条","heading":"","text":"有确凿证据表明投资性房地产的公允价值能够持续可靠取得的，可以对投资性房地产采用公允价值模式进行后续计量。 采用公允价值模式计量的，应当同时满足下列条件： （一）投资性房地产所在地有活跃的房地产交易市场； （二）企业能够从房地产交易市场上取得同类或类似房地产的市场价格及其他相关信息，从而对投资性房地产的公允价值作出合理的估计。","seq":9,"links":[{"doc_id":93,"tier":"L1","score":96,"rel_kind":"companion","target_seq":4,"target_art_no":"第5节","dir":"in","note":"指南详解（第5节）：锚定第十条（公允价值）"}]},{"id":103,"no":"第十一条","heading":"","text":"采用公允价值模式计量的，不对投资性房地产计提折旧或进行摊销，应当以资产负债表日投资性房地产的公允价值为基础调整其账面价值，公允价值与原账面价值之间的差额计入当期损益。","seq":10,"links":[{"doc_id":93,"tier":"L1","score":96,"rel_kind":"companion","target_seq":7,"target_art_no":"第8节","dir":"in","note":"指南详解（第8节）：锚定第十一条（公允价值、账面价值）"}]},{"id":104,"no":"第十二条","heading":"","text":"企业对投资性房地产的计量模式一经确定，不得随意变更。成本模式转为公允价值模式的，应当作为会计政策变更，按照《企业会计准则第28号——会计政策、会计估计变更和差错更正》处理。 已采用公允价值模式计量的投资性房地产，不得从公允价值模式转为成本模式。","seq":11,"links":[{"doc_id":93,"tier":"L1","score":96,"rel_kind":"companion","target_seq":5,"target_art_no":"第6节","dir":"in","note":"指南详解（第6节）：锚定第十二条（公允价值）"},{"doc_id":27,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第28号——会计政策、会计估计变更和差错更正》"}]},{"id":105,"no":"第十三条","heading":"","text":"企业有确凿证据表明房地产用途发生改变，满足下列条件之一的，应当将投资性房地产转换为其他资产或者将其他资产转换为投资性房地产： （一）投资性房地产开始自用。 （二）作为存货的房地产，改为出租。 （三）自用土地使用权停止自用，用于赚取租金或资本增值。 （四）自用建筑物停止自用，改为出租。","seq":12,"links":[{"doc_id":93,"tier":"L1","score":96,"rel_kind":"companion","target_seq":3,"target_art_no":"第4节","dir":"in","note":"指南详解（第4节）：锚定第十三条（条文主题匹配）"}]},{"id":106,"no":"第十四条","heading":"","text":"在成本模式下，应当将房地产转换前的账面价值作为转换后的入账价值。","seq":13},{"id":107,"no":"第十五条","heading":"","text":"采用公允价值模式计量的投资性房地产转换为自用房地产时，应当以其转换当日的公允价值作为自用房地产的账面价值，公允价值与原账面价值的差额计入当期损益。","seq":14,"links":[{"doc_id":93,"tier":"L1","score":96,"rel_kind":"companion","target_seq":2,"target_art_no":"第3节","dir":"in","note":"指南详解（第3节）：锚定第十五条（公允价值、账面价值）"},{"doc_id":93,"tier":"L1","score":96,"rel_kind":"companion","target_seq":7,"target_art_no":"第8节","dir":"in","note":"指南详解（第8节）：锚定第十五条（公允价值、账面价值）"}]},{"id":108,"no":"第十六条","heading":"","text":"自用房地产或存货转换为采用公允价值模式计量的投资性房地产时，投资性房地产按照转换当日的公允价值计价，转换当日的公允价值小于原账面价值的，其差额计入当期损益；转换当日的公允价值大于原账面价值的，其差额计入所有者权益。","seq":15,"links":[{"doc_id":93,"tier":"L1","score":96,"rel_kind":"companion","target_seq":2,"target_art_no":"第3节","dir":"in","note":"指南详解（第3节）：锚定第十六条（公允价值、账面价值）"}]},{"id":109,"no":"第十七条","heading":"","text":"当投资性房地产被处置，或者永久退出使用且预计不能从其处置中取得经济利益时，应当终止确认该项投资性房地产。","seq":16},{"id":110,"no":"第十八条","heading":"","text":"企业出售、转让、报废投资性房地产或者发生投资性房地产毁损，应当将处置收入扣除其账面价值和相关税费后的金额计入当期损益。","seq":17},{"id":111,"no":"第十九条","heading":"","text":"企业应当在附注中披露与投资性房地产有关的下列信息： （一）投资性房地产的种类、金额和计量模式。 （二）采用成本模式的，投资性房地产的折旧或摊销，以及减值准备的计提情况。 （三）采用公允价值模式的，公允价值的确定依据和方法，以及公允价值变动对损益的影响。 （四）房地产转换情况、理由，以及对损益或所有者权益的影响。 （五）当期处置的投资性房地产及其对损益的影响。","seq":18,"links":[{"doc_id":93,"tier":"L1","score":96,"rel_kind":"companion","target_seq":6,"target_art_no":"第7节","dir":"in","note":"指南详解（第7节）：锚定第十九条（公允价值）"}]}]});
